		const WQMT_MAINT_RE = /维护时间\s*[：:]\s*(\d{1,2})\s*月\s*(\d{1,2})\s*日\s*(\d{1,2})\s*[:：]\s*(\d{2})\s*[-~—–]\s*(\d{1,2})\s*[:：]\s*(\d{2})/;
